fn is_non_prime(n: u64) -> bool {
    if n == 2 {
        return false; // 2 is prime
    }
    
    let limit = (n as f64).sqrt() as u64; // Calculate the integer square root of n
    
    for k in 2..=limit {
        if n % k == 0 {
            return true; // Found a divisor, n is non-prime
        }
    }
    
    false // No divisors found, n is prime
}